const PROG = {"leaky":"import numpy as np\nimport pandas as pd\n\n\ndef get_features(db, entity_ids, seed_time):\n    # Feature frame indexed by entity\n    features = pd.DataFrame(index=entity_ids)\n    \n    # Keep only orders up to the prediction time\n    items = db['order_items']\n    items = items[items['ts'] <= seed_time]\n    \n    # Keep only the requested products\n    items_target = items[items['product_id'].isin(entity_ids)]\n    \n    # ---- Sales features (order_items) ----\n    agg_items = items_target.groupby('product_id').agg(\n        sales_count=('order_id', 'count'),\n        sum_price=('price', 'sum'),\n        avg_price=('price', 'mean'),\n        sum_freight=('freight_value', 'sum'),\n        avg_freight=('freight_value', 'mean'),\n        first_purchase_ts=('ts', 'min'),\n        last_purchase_ts=('ts', 'max'),\n        n_sellers=('seller_id', 'nunique')\n    )\n    \n    features = features.join(agg_items, how='left')\n    \n    # Days since first and last purchase\n    features['days_since_first'] = (seed_time - features['first_purchase_ts']).dt.days.fillna(99999)\n    features['days_since_last'] = (seed_time - features['last_purchase_ts']).dt.days.fillna(99999)\n    \n    # Drop helper columns\n    features = features.drop(columns=['first_purchase_ts', 'last_purchase_ts'])\n    \n    # ---- Review features (reviews) ----\n    if not items_target.empty:\n        review_data = items_target[['order_id', 'product_id']].merge(\n            db['reviews'][['order_id', 'review_score']],\n            on='order_id',\n            how='left'\n        )\n        review_agg = review_data.groupby('product_id').agg(\n            review_mean_score=('review_score', 'mean'),\n            review_count=('review_score', 'count')\n        )\n        features = features.join(review_agg, how='left')\n    else:\n        features['review_mean_score'] = np.nan\n        features['review_count'] = 0\n    \n    # Fill gaps with zeros\n    features = features.fillna(0)\n    \n    # Flag: was the product sold before\n    features['was_sold'] = (features['sales_count'] > 0).astype(int)\n    \n    # Keep the row order of entity_ids\n    features = features.reindex(entity_ids)\n    \n    return features\n","fixed":"import numpy as np\nimport pandas as pd\n\n\ndef get_features(db, entity_ids, seed_time):\n    # Feature frame indexed by entity\n    features = pd.DataFrame(index=entity_ids)\n    \n    # Keep only orders up to the prediction time\n    items = db['order_items']\n    items = items[items['ts'] <= seed_time]\n    \n    # Keep only the requested products\n    items_target = items[items['product_id'].isin(entity_ids)]\n    \n    # ---- Sales features (order_items) ----\n    agg_items = items_target.groupby('product_id').agg(\n        sales_count=('order_id', 'count'),\n        sum_price=('price', 'sum'),\n        avg_price=('price', 'mean'),\n        sum_freight=('freight_value', 'sum'),\n        avg_freight=('freight_value', 'mean'),\n        first_purchase_ts=('ts', 'min'),\n        last_purchase_ts=('ts', 'max'),\n        n_sellers=('seller_id', 'nunique')\n    )\n    \n    features = features.join(agg_items, how='left')\n    \n    # Days since first and last purchase\n    features['days_since_first'] = (seed_time - features['first_purchase_ts']).dt.days.fillna(99999)\n    features['days_since_last'] = (seed_time - features['last_purchase_ts']).dt.days.fillna(99999)\n    \n    # Drop helper columns\n    features = features.drop(columns=['first_purchase_ts', 'last_purchase_ts'])\n    \n    # ---- Review features (reviews) ----\n    if not items_target.empty:\n        review_data = items_target[['order_id', 'product_id']].merge(\n            db['reviews'].loc[db['reviews']['review_creation_date'] <= seed_time,\n                              ['order_id', 'review_score']],\n            on='order_id',\n            how='left'\n        )\n        review_agg = review_data.groupby('product_id').agg(\n            review_mean_score=('review_score', 'mean'),\n            review_count=('review_score', 'count')\n        )\n        features = features.join(review_agg, how='left')\n    else:\n        features['review_mean_score'] = np.nan\n        features['review_count'] = 0\n    \n    # Fill gaps with zeros\n    features = features.fillna(0)\n    \n    # Flag: was the product sold before\n    features['was_sold'] = (features['sales_count'] > 0).astype(int)\n    \n    # Keep the row order of entity_ids\n    features = features.reindex(entity_ids)\n    \n    return features\n","status":"import numpy as np\nimport pandas as pd\n\n\ndef get_features(db: dict, entity_ids, seed_time) -> pd.DataFrame:\n    # prepare tables\n    orders = db[\"orders\"]\n    items = db[\"order_items\"]\n    reviews = db[\"reviews\"]\n    payments = db[\"payments\"]\n\n    # keep only orders up to the prediction time\n    items_sel = items[items[\"ts\"] <= seed_time].copy()\n\n    # drop canceled orders (if the status exists)\n    order_status = orders[[\"order_id\", \"order_status\"]].drop_duplicates(\"order_id\")\n    items_sel = items_sel.merge(order_status, on=\"order_id\", how=\"left\")\n    items_sel = items_sel[items_sel[\"order_status\"] != \"canceled\"]\n    items_sel = items_sel[items_sel[\"product_id\"].isin(entity_ids)]\n\n    # ---- 1. basic product aggregates ----\n    base = items_sel.groupby(\"product_id\").agg(\n        num_orders=(\"order_id\", \"nunique\"),\n        num_items=(\"order_id\", \"size\"),\n        total_price=(\"price\", \"sum\"),\n        total_freight=(\"freight_value\", \"sum\"),\n        avg_price=(\"price\", \"mean\"),\n        avg_freight=(\"freight_value\", \"mean\"),\n        num_sellers=(\"seller_id\", \"nunique\"),\n        last_order_ts=(\"ts\", \"max\")\n    ).reset_index()\n\n    # ---- 2. orders in the last 30/90/180 days ----\n    for days, col_name in [(30, \"orders_30d\"), (90, \"orders_90d\"), (180, \"orders_180d\")]:\n        cutoff = seed_time - pd.Timedelta(days=days)\n        cnt = items_sel[items_sel[\"ts\"] >= cutoff].groupby(\"product_id\").size().rename(col_name).reset_index()\n        base = base.merge(cnt, on=\"product_id\", how=\"left\")\n        base[col_name] = base[col_name].fillna(0).astype(int)\n\n    # ---- 3. review features (created before seed_time only) ----\n    reviews_sel = reviews[reviews[\"review_creation_date\"] <= seed_time]\n    items_rev = items_sel[[\"order_id\", \"product_id\"]].merge(\n        reviews_sel[[\"order_id\", \"review_score\"]], on=\"order_id\", how=\"inner\"\n    )\n    rev_agg = items_rev.groupby(\"product_id\").agg(\n        review_count=(\"review_score\", \"count\"),\n        avg_review_score=(\"review_score\", \"mean\"),\n        pos_review_rate=(\"review_score\", lambda x: (x >= 4).mean())\n    ).reset_index()\n    base = base.merge(rev_agg, on=\"product_id\", how=\"left\")\n\n    # ---- 4. payment features (per order, then per product) ----\n    pay_order = payments.groupby(\"order_id\").agg(\n        payment_sum=(\"payment_value\", \"sum\"),\n        payment_mean=(\"payment_value\", \"mean\"),\n        installments_mean=(\"payment_installments\", \"mean\"),\n        credit_card_share=(\"payment_type\", lambda x: (x == \"credit_card\").mean())\n    ).reset_index()\n\n    items_pay = items_sel[[\"order_id\", \"product_id\"]].merge(pay_order, on=\"order_id\", how=\"inner\")\n    pay_prod = items_pay.groupby(\"product_id\").agg(\n        avg_payment_sum=(\"payment_sum\", \"mean\"),\n        avg_payment_mean=(\"payment_mean\", \"mean\"),\n        avg_installments=(\"installments_mean\", \"mean\"),\n        avg_credit_card_share=(\"credit_card_share\", \"mean\")\n    ).reset_index()\n    base = base.merge(pay_prod, on=\"product_id\", how=\"left\")\n\n    # ---- 5. recency of the last order ----\n    last = pd.to_datetime(base[\"last_order_ts\"])\n    recency = (seed_time - last).dt.days\n    recency = recency.fillna(999)\n    base[\"recency_days\"] = recency\n    base = base.drop(columns=[\"last_order_ts\"])\n\n    # ---- reindex to the requested product_ids ----\n    base = base.set_index(\"product_id\")\n    result = base.reindex(entity_ids)\n\n    # fill gaps: reviews/payments/counts 0, recency a large value\n    if \"recency_days\" in result.columns:\n        result[\"recency_days\"] = result[\"recency_days\"].fillna(999)\n    result = result.fillna(0)\n\n    return result\n"};
